                .sorted(Comparator.comparing((Claim c) -> openedOn(c, logOf.get(c.getId())))
                        .thenComparing(Claim::getId))
                .toList()) {
            claim.setNumber(claimService.nextNumber(to, claim.getDueBy()));
        }
